#!/usr/bin/env python3
"""scoring_and_ai.py — 4-Pillar Fit Scoring, 5-Point AI Output Grounding Verifier & Gemini DM Synthesis"""
from __future__ import annotations
import json, os, re, urllib.parse
from typing import Any, Dict, List
import config

SPAM_TERMS = ["memecoin", "airdrop", "100x", "paid promo", "$aibot"]
ROBOTICS_TERMS = ["robotics", "embodied ai", "bimanual", "vla", "sim2real", "manipulation", "slam", "rover", "visuotactile", "6-dof", "robot", "autonomous", "lerobot", "gr00t", "humanoid"]
AI_INFRA_TERMS = ["vllm", "triton", "quantized", "vlm", "llm", "inference", "kv-cache", "agent", "mcp", "evals", "world models", "ai", "ml", "deep learning", "rag"]
SEA_TERMS = ["vietnam", "ho chi minh", "hcmc", "hanoi", "da nang", "singapore", "nus", "hcmut", "hcmus", "jakarta", "indonesia", "sea", "asean", "southeast asia"]
HOOK_TERMS = ["pilot", "design-partner", "pre-seed", "open-source", "benchmarked", "field-tested", "shipped", "testing", "collaboration", "discussions", "released"]
STOP_WORDS = {"just", "with", "from", "that", "this", "have", "looking", "building", "open", "across", "the", "and", "for", "our"}

def classify_archetype(bio_lower: str, posts_lower: str) -> str: c = f"{bio_lower} {posts_lower}"; return "Noise / Promo" if any(k in c for k in SPAM_TERMS) else ("Founder / Spinout Builder" if any(k in c for k in ["founder", "co-founder", "spinning this out", "pre-seed", "ceo", "building"]) else ("AI & Robotics Researcher" if any(k in c for k in ["phd", "research scientist", "paper", "nus", "hcmut", "diffusion policies", "lab", "scientist"]) else ("AI Infra / Systems Engineer" if any(k in c for k in ["vllm", "triton", "kv-cache", "mcp", "infra", "runtime", "engineer", "developer"]) else "AI & Robotics Builder")))

def evaluate_candidate_fit(candidate: Dict[str, Any], query_segment: str) -> Dict[str, Any]: bio_l = candidate.get("bio", "").lower(); loc_l = candidate.get("location", "").lower(); posts = candidate.get("recent_posts", []); posts_txt = " ".join(p.get("text", "") for p in posts).lower(); combined = f"{bio_l} {loc_l} {posts_txt}"; arch = classify_archetype(bio_l, posts_txt); is_spam = any(k in combined for k in SPAM_TERMS); mr = [t for t in ROBOTICS_TERMS if t in combined]; ma = [t for t in AI_INFRA_TERMS if t in combined]; msea = [t for t in SEA_TERMS if t in combined]; mh = [t for t in HOOK_TERMS if t in combined]; tech = min(35, 14 + (min(21, 13 + 4 * len(mr)) if mr else 0) + ((min(21, 11 + 4 * len(ma)) if not mr else min(8, 3 * len(ma))) if ma else 0)); sea = 25 if len(msea) >= 2 else (20 if len(msea) == 1 else 14); readiness = min(25, 12 + 5 * len(mh)) if mh else 12; q_toks = [tok.strip().lower() for tok in query_segment.replace(",", " ").split() if len(tok.strip()) > 2]; snr = min(15, (14 if bool(re.search(r"\b(\d+(\.\d+)?(ms|x|%|gb|dof|ha|hrs|hours|\$))\b", combined)) else 12) + (1 if (q_toks and any(tok in combined for tok in q_toks)) else 0)); reasons = ([f"Embodied AI / Robotics depth ({', '.join(mr[:3])})"] if mr else []) + ([f"AI Infra / Models / Agentic signal ({', '.join(ma[:3])})"] if ma else []) + ([f"Southeast Asia ecosystem footprint ({candidate.get('location', 'SEA')})"] if msea else []) + ([f"High-intent conversation hook ({', '.join(mh[:2])})"] if mh else []); reasons = reasons or ["Relevant AI & Robotics profile verified via live X discovery"]; best_p = posts[0] if posts else {"text": candidate.get("bio", ""), "url": f"{config.X_WEB}/{candidate['username']}"}; return ({"fit_score": 6, "role_archetype": arch, "score_breakdown": {"technical_depth": 0, "sea_ecosystem_fit": 0, "conversation_readiness": 0, "signal_to_noise": 6}, "fit_reasons": ["Excluded (Noise Filter): Promotional token/airdrop pattern."], "evidence_quote": best_p.get("text", ""), "evidence_url": best_p.get("url", "")} if is_spam else {"fit_score": min(99, tech + sea + readiness + snr), "role_archetype": arch, "score_breakdown": {"technical_depth": tech, "sea_ecosystem_fit": sea, "conversation_readiness": readiness, "signal_to_noise": snr}, "fit_reasons": reasons, "evidence_quote": best_p.get("text", "") or candidate.get("bio", ""), "evidence_url": best_p.get("url", f"{config.X_WEB}/{candidate['username']}")})

def verify_dm_grounding(draft_dm: str, candidate: Dict[str, Any]) -> Dict[str, Any]: text = (draft_dm or "").strip(); lower_dm = text.lower(); ev_txt = f"{candidate.get('bio', '')} {candidate.get('evidence_quote', '')} {candidate.get('username', '')}".lower(); ev_tokens = {tok for tok in re.findall(r"[a-z0-9\-\.]{3,}", ev_txt) if tok not in STOP_WORDS}; matched = [tok for tok in ev_tokens if tok in lower_dm]; has_anchor = len(matched) >= 1; cliches = [c for c in config.BANNED_CLICHES if c in lower_dm]; no_cliche = len(cliches) == 0; has_q = "?" in text; len_ok = 50 <= len(text) <= 480; no_links = not bool(re.search(config.SCHEME + r"?" + config.SEP, text)); checks = [{"rule": "Evidence Anchor", "passed": has_anchor, "detail": f"Matched tokens: {', '.join(matched[:4])}"}, {"rule": "Zero Invented Familiarity", "passed": no_cliche, "detail": "No fake flattery cliches"}, {"rule": "Conversational Question Hook", "passed": has_q, "detail": "Ends with question (?)"}, {"rule": "Optimal DM Length (50-480 chars)", "passed": len_ok, "detail": f"{len(text)} chars"}, {"rule": "Link-Free Cold DM Policy", "passed": no_links, "detail": "No URLs in cold DM"}]; passed = sum(1 for c in checks if c["passed"]); return {"all_passed": passed == len(checks), "score_label": f"{passed}/{len(checks)} Checks Passed", "matched_anchors": matched[:5], "checks": checks}

def _call_gemini(m_url: str, key: str, prompt: str, candidate: Dict[str, Any]) -> str: ok, d = config.fetch_json(f"{m_url}?key={urllib.parse.quote(key)}", headers={"Content-Type": "application/json"}, data=json.dumps({"contents": [{"parts": [{"text": prompt}]}]}).encode("utf-8"), method="POST", timeout=10); txt = (d.get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text", "").strip().strip('"') if (ok and isinstance(d, dict)) else ""); return txt if (txt and verify_dm_grounding(txt, candidate)["all_passed"]) else ""

def generate_grounded_dm(candidate: Dict[str, Any], gemini_key: str = "", sender_context: str = "GenAI Fund") -> str: raw_name = candidate.get("display_name", "") or candidate.get("username", "there"); first_name = raw_name.split("|")[0].replace("Dr.", "").strip().split()[0] if raw_name else "there"; ev_quote = (candidate.get("evidence_quote") or candidate.get("bio") or "").strip(); uname = candidate.get("username", ""); loc = candidate.get("location") or "Southeast Asia"; active_key = gemini_key.strip() or os.getenv("GEMINI_API_KEY", "").strip(); prompt = f"Write a short, natural X Direct Message (160-380 chars) from {sender_context} to {first_name} (@{uname}, {loc}). Reference their bio/post: '{ev_quote}'. Zero fake flattery, no URLs, end with a technical question '?'."; gem_hits = ([_call_gemini(m, active_key, prompt, candidate) for m in config.GEMINI_API_MODELS] if active_key else []); valid_gem = [g for g in gem_hits if g]; short_ev = (ev_quote[:110] + "...") if len(ev_quote) > 110 else (ev_quote or f"your AI & robotics work on @{uname}"); return (valid_gem[0] if valid_gem else f"Hi {first_name} - came across your recent update on @{uname} ('{short_ev}') and your work in {loc}. At GenAI Fund we partner with technical AI and robotics builders across Southeast Asia on enterprise pilots and ecosystem growth. What technical milestones or pilot use cases are you focusing on next?")

def classify_reply_intent(reply_text: str) -> Dict[str, Any]: low = reply_text.lower(); is_opt = any(k in low for k in ["unsubscribe", "not interested", "stop", "remove me"]); is_warm = ("?" in reply_text or any(k in low for k in ["call", "chat", "pilot", "deck", "next week", "tuesday", "thursday", "sure", "interested", "coffee", "zoom", "meet", "yes"])); return ({"reply_intent": "opt_out", "prospect_status": "blocked", "needs_attention": 0, "attention_reason": "Opt-out requested - moved to Blocked"} if is_opt else ({"reply_intent": "warm_interest_or_question", "prospect_status": "needs_attention", "needs_attention": 1, "attention_reason": "High-Priority Warm Reply - Ready for FDE Partner takeover"} if is_warm else {"reply_intent": "general_reply", "prospect_status": "replied", "needs_attention": 1, "attention_reason": "Inbound reply received - review thread"}))
